import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const P=JSON.parse('{"title":"科学日报 · 2026-11-07（生物医学 · 体内碱基编辑降脂 / 手表 AI 查高血压）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-11-07-biomed.md","filePath":"topics/biomedicine/science-daily-2026-11-07-biomed.md"}'),e={name:"topics/biomedicine/science-daily-2026-11-07-biomed.md"};function i(g,o,l,a,c,d){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-11-07-生物医学-·-体内碱基编辑降脂-手表-ai-查高血压" tabindex="-1">科学日报 · 2026-11-07（生物医学 · 体内碱基编辑降脂 / 手表 AI 查高血压） <a class="header-anchor" href="#科学日报-·-2026-11-07-生物医学-·-体内碱基编辑降脂-手表-ai-查高血压" aria-label="Permalink to &quot;科学日报 · 2026-11-07（生物医学 · 体内碱基编辑降脂 / 手表 AI 查高血压）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-07.md</code> — 第57期 ｜ 科学板块（生物医学向 2 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边。</p></blockquote><hr><h2 id="科学日报-2026-11-07-生物医学-1-2-一次给药、肝脏定点改一个碱基-把-angptl3-关掉" tabindex="-1">科学日报 2026-11-07（生物医学 1/2）：一次给药、肝脏定点改一个碱基，把 ANGPTL3 关掉 <a class="header-anchor" href="#科学日报-2026-11-07-生物医学-1-2-一次给药、肝脏定点改一个碱基-把-angptl3-关掉" aria-label="Permalink to &quot;科学日报 2026-11-07（生物医学 1/2）：一次给药、肝脏定点改一个碱基，把 ANGPTL3 关掉&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-07.md</code> ｜ DOI: 10.1038/s41586-026-11233-9 ｜ Nature (2026)</p></blockquote><ul><li>问题：LDL-C 与<strong>富甘油三酯脂蛋白</strong>是动脉粥样硬化性心血管病的首要风险因素，已有多款降脂药，但<strong>慢性病照护模式</strong>下多数患者<strong>长期达不到目标值</strong>。能不能把「每天吃药」换成「<strong>改一次基因</strong>」？</li><li>方法：<strong>GalNAc–脂质纳米粒</strong>同时封装 <strong>guide RNA</strong> 与<strong>编码 CRISPR 腺嘌呤碱基编辑器（ABE）的 mRNA</strong>，静脉给药后<strong>肝选择性</strong>导入，在 <strong>ANGPTL3</strong> 位点做单碱基对改变从而<strong>永久失活</strong>该基因。</li><li>结果（实测）： <ul><li>人肝细胞体外：目标位点碱基对改变，<strong>约 3000 个候选位点无脱靶编辑</strong>、无治疗相关结构变异；</li><li><strong>非人灵长类</strong>单次输注耐受良好，循环 ANGPTL3 蛋白<strong>平均降 &gt;90%</strong>，<strong>疗效确认持续 3 年</strong>；</li><li>高脂血症<strong>小鼠与猴</strong>模型：<strong>LDL-C 降约 40%–50%</strong>、<strong>甘油三酯降 50%–70%</strong>；</li><li>已支撑一项<strong>难治性高脂血症首次人体试验</strong>启动。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>materials</code>（LNP 递送））： <ol><li><strong>「一次性疗法」的真正门槛不是编辑效率，是脱靶证据的规模</strong>——3000 候选位点 + 3 年持久性，这两项才是监管与临床能接受的「一次」；判据：<strong>任何&quot;一针永久&quot;的方案，先看它给了多大的安全性搜索面</strong>。</li><li><strong>选靶点的逻辑变了</strong>：ANGPTL3 属「<strong>功能缺失有益</strong>」的基因（人天然缺失者也低血脂），天然敲除人群即是长期安全性数据；判据：<strong>想用永久编辑，优先挑「人类自然实验已证明敲掉更好」的靶点</strong>。</li><li>与 11-04 那期「HX1 脂质纳米粒把 mRNA 送进脑」串起来看：<strong>LNP 正在从&quot;疫苗载体&quot;变成&quot;器官可寻址的递送总线&quot;</strong>（肝靠 GalNAc、脑靠跨屏障脂质），编辑工具本身反而越来越标准化。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-07-生物医学-2-2-手表不量血压-也能筛出高血压" tabindex="-1">科学日报 2026-11-07（生物医学 2/2）：手表不量血压，也能筛出高血压 <a class="header-anchor" href="#科学日报-2026-11-07-生物医学-2-2-手表不量血压-也能筛出高血压" aria-label="Permalink to &quot;科学日报 2026-11-07（生物医学 2/2）：手表不量血压，也能筛出高血压&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-07.md</code> ｜ DOI: 10.1038/s41586-026-11336-3 ｜ Nature (2026)</p></blockquote><ul><li>问题：高血压是「<strong>沉默杀手</strong>」，<strong>过半患者不知情</strong>；而早干预的价值极高。能否用<strong>已普及的消费级手表</strong>做<strong>无症状人群的机会性筛查</strong>（而不是又造一台血压计）？</li><li>方法：<strong>AI-PPG-ACC-HTN</strong>——把 <strong>PPG（光电容积脉搏波）+ 加速度</strong>两路波形喂给 AI，<strong>不做任何袖带校准</strong>；<strong>前瞻、多中心</strong>验证 <strong>196 名</strong>无已知心血管病、未服降压药的受试者，金标准为 <strong>24 小时动态血压监测</strong>，连续 <strong>7 天</strong>真实世界监测。</li><li>结果（实测）： <ul><li><strong>敏感度 65.8%</strong>（95% CI 54.0–76.3）、<strong>特异度 90.0%</strong>（83.2–94.7）、<strong>PPV 80.6%</strong>（68.6–89.6）；</li><li>对照<strong>诊室血压初筛</strong>：敏感度 <strong>55.3%</strong>、特异度 90.0%、PPV 77.8%；</li><li>定位明确：<strong>不替代袖带诊断</strong>，而是把高危个体<strong>推向临床确诊</strong>的入口。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>fitness</code>（可穿戴数据））： <ol><li><strong>「机会性筛查」的正确指标不是准确率，是 PPV + 后续转诊闭环</strong>——特异度 90% 意味着<strong>每 10 个报警 1 个假阳</strong>，在低患病率人群里这就是主要成本；判据：<strong>评估任何&quot;顺手筛查&quot;类 AI，先问人群患病率与转诊路径</strong>。</li><li>与 11-06 的「肝转移重创造血」「睡眠 REM 微结构与 AD」一起看：<strong>可穿戴 + 多模态波形正在把&quot;疾病信号&quot;从&quot;症状主诉&quot;改成&quot;生理时间序列的统计偏移&quot;</strong>——这也意味着<strong>隐私与过度诊断</strong>的风险同步上升（本库已在 <code>science-news</code> 记录过「脑扫描安全帽」的隐私争议）。</li></ol></li></ul><hr><blockquote><p>关键词：ANGPTL3、碱基编辑、ABE、GalNAc、脂质纳米粒、LNP、LDL-C、甘油三酯、一次性疗法、脱靶编辑、非人灵长类、心血管、高血压、机会性筛查、PPG、加速度计、可穿戴、动态血压监测、敏感度、特异度、PPV、过度诊断、科学日报第57期、改路径优于加力度、否证性判据优于肯定性判据</p></blockquote>',12)])])}const m=t(e,[["render",i]]);export{P as __pageData,m as default};
